//! Offline fixtures: the invented Acme change form (from the golden file
//! generated by `tests/golden/gen_flows.py`), a fake client, an in-memory
//! journal and a recording change writer.

use std::path::PathBuf;
use std::sync::{Arc, LazyLock, Mutex};

use serde_json::{Map, Value as Json, json};

use fsv_api::service::Api;
use fsv_core::client::{Body, Response};
use fsv_core::error::{ApiError, Error, Result};
use fsv_forms::tz::TzEnv;

use crate::change::{ChangeWriter, PlanJournal, PlanRecord, recent_plan_rows};
use crate::meta::{ClientResolver, FormMeta, Resolver};

pub const FETCHED_AT: f64 = 1900000000.0;
pub const BASE: &str = "/work/drafts";

pub static GOLDEN: LazyLock<Json> = LazyLock::new(|| {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/golden/flows.json");
    serde_json::from_str(&std::fs::read_to_string(p).expect("golden file")).expect("golden json")
});

pub fn golden(path: &[&str]) -> &'static Json {
    path.iter().fold(&*GOLDEN, |v, k| &v[*k])
}

pub fn acme_meta(module: &str, form_type: &str) -> FormMeta {
    acme_meta_id(module, form_type, Json::Null)
}

pub fn acme_meta_id(module: &str, form_type: &str, module_id: Json) -> FormMeta {
    let mut fields = golden(&["fields"]).clone();
    if module == "ticket" {
        fields = json!({"ticket_fields": fields["change_fields"].clone()});
    }
    FormMeta::new(
        module,
        form_type,
        fields,
        golden(&["rules"]).clone(),
        json!(2),
        FETCHED_AT,
        "server",
        module_id,
    )
    .expect("acme meta")
    .with_tz_env(TzEnv::empty())
}

