/// What a write call failed with.
#[derive(Clone)]
pub enum Fail {
    Api(u16),
    Timeout,
}

/// Records every call; serves the Acme lookups. No network.
#[derive(Default)]
pub struct FakeApi {
    pub calls: Mutex<Vec<(String, String, Json)>>,
    pub failure: Mutex<Option<Fail>>,
    pub ticket_read: Mutex<Option<Json>>,
    /// Rows every `lookup_choices` returns (`None`: Acme people by name).
    pub link_rows: Mutex<Option<Vec<Json>>>,
    /// `(link, query)` of each `lookup_choices` call.
    pub link_calls: Mutex<Vec<(String, String)>>,
}

impl FakeApi {
    pub fn writes(&self) -> Vec<(String, String, Json)> {
        self.calls
            .lock()
            .unwrap()
            .iter()
            .filter(|c| c.0 == "POST" || c.0 == "PUT")
            .cloned()
            .collect()
    }
}

impl Api for FakeApi {
    fn int_get(&self, path: &str, _params: Option<Map<String, Json>>) -> Result<Json> {
        self.calls
            .lock()
            .unwrap()
            .push(("GET".into(), path.into(), Json::Null));
        if path == "bootstrap/agents_groups" {
            return Ok(json!({"groups": [{"id": 9000009001i64, "name": "Platform Ops"}]}));
        }
        if path.starts_with("tickets/") {
            return match self.ticket_read.lock().unwrap().clone() {
                Some(v) => Ok(v),
                None => Err(Error::Api(ApiError::new(404, json!("not found")))),
            };
        }
        Ok(json!({}))
    }
    fn int_post(&self, path: &str, body: &Json) -> Result<Json> {
        self.calls
            .lock()
            .unwrap()
            .push(("POST".into(), path.into(), body.clone()));
        Ok(json!({"ok": true}))
    }
    fn int_put(&self, path: &str, body: &Json) -> Result<Json> {
        self.calls
            .lock()
            .unwrap()
            .push(("PUT".into(), path.into(), body.clone()));
        Ok(json!({}))
    }
    fn int_patch(&self, _path: &str, _body: &Json) -> Result<Json> {
        Ok(json!({}))
    }
    fn int_delete(
        &self,
        _path: &str,
        _body: Option<&Json>,
        _params: Option<Map<String, Json>>,
    ) -> Result<Json> {
        Ok(json!({}))
    }
    fn autocomplete(
        &self,
        kind: &str,
        query: &str,
        _params: Option<Map<String, Json>>,
    ) -> Result<Vec<Json>> {
        let q = fsv_core::pystr::casefold(query);
        let pool = if kind == "requesters" {
            people()
        } else {
            agents()
        };
        Ok(pool
            .into_iter()
            .filter(|p| {
                fsv_core::pystr::casefold(p["value"].as_str().unwrap_or("")).contains(&q)
                    || p["email"].as_str().unwrap_or("").contains(&q)
            })
            .collect())
    }
    fn lookup_choices(&self, link: &str, query: &str) -> Result<Vec<Json>> {
        self.link_calls
            .lock()
            .unwrap()
            .push((link.into(), query.into()));
        if let Some(rows) = self.link_rows.lock().unwrap().clone() {
            return Ok(rows);
        }
        let q = fsv_core::pystr::casefold(query);
        Ok(people()
            .into_iter()
            .filter(|p| fsv_core::pystr::casefold(p["value"].as_str().unwrap_or("")).contains(&q))
            .map(|p| json!({"id": p["id"], "name": p["value"]}))
            .collect())
    }
    fn fulltext_search(
        &self,
        _entity: &str,
        _term: &str,
        _page: i64,
        _sort: Option<&str>,
    ) -> Result<Json> {
        Ok(json!({}))
    }
    fn get_csrf(&self) -> Result<String> {
        Ok("synthetic-token".into())
    }
    fn send_once(
        &self,
        method: &str,
        path: &str,
        body: Body,
        _params: Option<Map<String, Json>>,
        csrf: &str,
    ) -> Result<Json> {
        let Body::Raw(bytes) = body else {
            return Err(Error::other("expected raw body"));
        };
        let doc: Json = serde_json::from_slice(&bytes).expect("json body");
        self.calls.lock().unwrap().push((
            method.into(),
            path.into(),
            json!({"csrf": csrf, "body": doc}),
        ));
        match self.failure.lock().unwrap().clone() {
            Some(Fail::Api(status)) => Err(Error::Api(ApiError::new(
                status,
                json!("do not print response body"),
            ))),
            Some(Fail::Timeout) => Err(Error::Http {
                kind: "ReadTimeout".into(),
                message: "sensitive body".into(),
            }),
            None => Ok(json!({"ticket": {"id": 123}})),
        }
    }
    fn fetch(&self, _url: &str) -> Result<Response> {
        Err(Error::other("no network"))
    }
    fn domain(&self) -> String {
        "acme.example.com".into()
    }
}

pub fn fake_client() -> Arc<FakeApi> {
    Arc::new(FakeApi::default())
}

pub fn fake_resolver() -> Arc<ClientResolver> {
    Arc::new(ClientResolver::new(fake_client()))
}

pub fn resolver_arc() -> Option<Arc<dyn Resolver>> {
    Some(fake_resolver() as Arc<dyn Resolver>)
}

/// In-memory plan journal (`journal.read` / `record_plan` / `recent_plan`).
#[derive(Default)]
pub struct MemJournal {
    pub rows: Mutex<Vec<Json>>,
    pub drop_writes: bool,
}

impl PlanJournal for MemJournal {
    fn read(&self) -> Vec<Json> {
        self.rows.lock().unwrap().clone()
    }
    fn record_plan(&self, event: &str, plan: &str, action: &str, extra: PlanRecord<'_>) {
        if self.drop_writes {
            return;
        }
        let mut rows = self.rows.lock().unwrap();
        let epoch = rows.len() as f64 + 1.0;
        let mut row = json!({"ts": "2030-01-01T00:00:00", "epoch": epoch, "kind": format!("plan:{action}"),
                             "event": event, "plan": plan,
                             "target": extra.target.cloned().unwrap_or(Json::Null),
                             "created_id": extra.created_id.cloned().unwrap_or(Json::Null)});
        if let Some(steps) = extra.steps {
            row["steps"] = Json::Array(steps.to_vec());
        }
        if extra.error {
            row["error"] = json!("details omitted");
        }
        rows.push(row);
    }
    fn recent_plan(&self, plan: &str, action: &str, _hours: f64) -> Option<Json> {
        recent_plan_rows(&self.read(), plan, action, f64::MIN)
    }
}

/// Records create.py calls; ids from 9000005001.
#[derive(Default)]
pub struct FakeWriter {
    pub calls: Mutex<Vec<(String, Json)>>,
    pub fail_upload: bool,
    pub fail_post: Option<u16>,
}

impl ChangeWriter for FakeWriter {
    fn upload_file(&self, path: &str) -> Result<Json> {
        if self.fail_upload {
            return Err(Error::other("upload refused"));
        }
        let mut calls = self.calls.lock().unwrap();
        let n = calls.iter().filter(|c| c.0 == "upload").count() as i64;
        calls.push(("upload".into(), json!(path)));
        Ok(json!(9000005001i64 + n))
    }
    fn post_change_body(&self, body: &Map<String, Json>) -> Result<Json> {
        self.calls
            .lock()
            .unwrap()
            .push(("post".into(), Json::Object(body.clone())));
        if let Some(status) = self.fail_post {
            return Err(Error::Api(ApiError::new(status, json!("rejected"))));
        }
        Ok(json!({"id": 900000502, "human_display_id": "CHN-502"}))
    }
    fn put_change_body(&self, change_id: &Json, body: &Map<String, Json>) -> Result<Json> {
        self.calls
            .lock()
            .unwrap()
            .push(("put".into(), json!({"id": change_id, "body": body})));
        Ok(json!({"id": change_id}))
    }
    fn attach_files_to_change(
        &self,
        change_id: &Json,
        paths: &[String],
        duplicate: &str,
    ) -> Result<()> {
        self.calls.lock().unwrap().push((
            "attach".into(),
            json!({"id": change_id, "paths": paths, "duplicate": duplicate}),
        ));
        Ok(())
    }
    fn update_planning_field(
        &self,
        change_id: &Json,
        req: &crate::change::PlanningUpdate<'_>,
    ) -> Result<()> {
        self.calls.lock().unwrap().push((
            "planning".into(),
            json!({"id": change_id, "field": req.field_id, "description": req.description,
                   "files": req.file_paths, "duplicate": req.duplicate, "label": req.label}),
        ));
        Ok(())
    }
}
